-- Migration: Year 2 - Renal/Urinary Pathology MCQ Bank (PART 4: 226-300)
-- Topics: Renal Neoplasms, Vascular Disorders, UTIs, Renal Tubular Acidosis
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Renal/Urinary Pathology', 'renal-urinary-pathology', 3, 2, 50)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- RENAL NEOPLASMS (226-245)
    (v_topic_id, '226. What is the classic triad of Renal Cell Carcinoma (RCC)?', '["Hematuria, flank pain, and palpable mass", "Proteinuria, edema, and hyperlipidemia", "Fever, rash, and eosinophilia", "Polyuria, polydipsia, and hypernatremia"]', 0, 'The classic triad is gross hematuria, flank pain, and a palpable abdominal mass. However, all three are present together in less than 10% of cases today (usually caught earlier on imaging).'),
    (v_topic_id, '227. Renal Cell Carcinoma originates from which cells?', '["Transitional epithelium of the renal pelvis", "Proximal tubule epithelial cells", "Distal tubule epithelial cells", "Mesangial cells"]', 1, 'Clear cell RCC (the most common subtype) arises from the epithelial cells of the proximal convoluted tubule.'),
    (v_topic_id, '228. The most common histological variant of RCC is "Clear Cell". Why do the cells appear clear?', '["They are filled with water", "They are filled with lipid and glycogen", "They lack a nucleus", "They are filled with mucin"]', 1, 'The cells are packed with lipids and glycogen, which dissolve during slide preparation, leaving clear cytoplasm.'),
    (v_topic_id, '229. A strong, modifiable risk factor for sporadic Renal Cell Carcinoma is?', '["Smoking", "Alcohol use", "High-calcium diet", "IV drug use"]', 0, 'Smoking is the most significant modifiable risk factor. Obesity and hypertension are also major risk factors.'),
    (v_topic_id, '230. Sporadic Clear Cell RCC is highly associated with a somatic mutation in which gene?', '["PKD1", "WT1", "VHL (Von Hippel-Lindau)", "p53"]', 2, 'Loss of the VHL tumor suppressor gene on chromosome 3 is the driving mutation in both sporadic and familial Clear Cell RCC.'),
    (v_topic_id, '231. How does loss of the VHL gene lead to cancer?', '["It directly stimulates cell division", "It prevents the degradation of HIF-1 (Hypoxia-Inducible Factor), leading to massive VEGF and PDGF production", "It prevents apoptosis", "It causes massive DNA damage"]', 1, 'HIF-1 normally degrades in the presence of oxygen. Without VHL to tag it for destruction, HIF-1 accumulates, tricking the cell into thinking it is hypoxic. It secretes massive amounts of angiogenic factors (VEGF), making the tumor highly vascular.'),
    (v_topic_id, '232. RCC is notorious for paraneoplastic syndromes. Which hormone can it secrete to cause polycythemia?', '["PTHrP", "ACTH", "Erythropoietin (EPO)", "Renin"]', 2, 'RCC can secrete EPO (causing reactive polycythemia), PTHrP (hypercalcemia), Renin (hypertension), and ACTH (Cushing syndrome).'),
    (v_topic_id, '233. How does RCC typically spread?', '["Directly into the colon", "Via lymphatics only", "Hematogenously via the Renal Vein to the IVC", "Via the ureter to the bladder"]', 2, 'RCC has a unique propensity to invade the renal vein, growing as a solid column of tumor up the IVC and potentially right into the right atrium. It frequently metastasizes to the lungs and bone.'),
    (v_topic_id, '234. A left-sided varicocele in an older man that does NOT empty when he lies down should raise suspicion for?', '["Testicular cancer", "Renal Cell Carcinoma invading the left renal vein", "Benign prostatic hyperplasia", "Aortic aneurysm"]', 1, 'The left gonadal vein drains into the left renal vein. An RCC blocking the left renal vein causes blood to back up, creating a varicocele. (The right gonadal drains directly to the IVC, so a right varicocele is less common from RCC unless the IVC is blocked).'),
    (v_topic_id, '235. Wilms Tumor (Nephroblastoma) is the most common renal malignancy in young children. What is the classic presentation?', '["Gross hematuria with severe pain", "A massive, palpable, unilateral flank mass in an otherwise healthy-appearing child", "Bilateral cystic kidneys", "Renal failure"]', 1, 'It typically presents around age 3 as a huge, smooth, unilateral abdominal mass (often noticed by a parent giving the child a bath).'),
    (v_topic_id, '236. Wilms Tumor is comprised of?', '["Clear cells", "Transitional cells", "Triphasic tissue: Blastema (small blue cells), stroma, and primitive tubules/epithelium", "Mature bone and cartilage"]', 2, 'It is an embryonal tumor containing embryonic glomerular structures (blastema, primitive stroma, and epithelium).'),
    (v_topic_id, '237. The WAGR complex is associated with a deletion of the WT1 gene on chromosome 11. What does WAGR stand for?', '["Wilms tumor, Aniridia, Genitourinary anomalies, and Mental Retardation", "Wilms tumor, Agenesis of kidney, Growth restriction, Retinoblastoma", "Wilms tumor, Angiomyolipoma, Gonadal dysgenesis, Renal failure", "Wilms tumor, Ataxia, Glaucoma, Rash"]', 0, 'Aniridia (absence of the iris) is a key clinical clue for this genetic syndrome.'),
    (v_topic_id, '238. Denys-Drash Syndrome is characterized by Wilms tumor, progressive renal (glomerular) disease, and?', '["Aniridia", "Macroglossia", "Male pseudohermaphroditism", "Hemihypertrophy"]', 2, 'It involves WT1 mutations leading to early-onset nephrotic syndrome and ambiguous genitalia/pseudohermaphroditism.'),
    (v_topic_id, '239. Beckwith-Wiedemann Syndrome is characterized by Wilms tumor, neonatal hypoglycemia, muscular hemihypertrophy, and?', '["Aniridia", "Organomegaly (including macroglossia)", "Deafness", "Cataracts"]', 1, 'It involves an alteration of the WT2 gene locus (imprinting defect), leading to overgrowth (macroglossia, macrosomia) and embryonal tumors (Wilms, hepatoblastoma).'),
    (v_topic_id, '240. An Angiomyolipoma is a benign kidney tumor. It is highly associated with which genetic disease?', '["Von Hippel-Lindau", "Tuberous Sclerosis", "Neurofibromatosis", "Polycystic Kidney Disease"]', 1, 'Tuberous sclerosis presents with cortical tubers, ash-leaf spots, cardiac rhabdomyomas, and bilateral renal angiomyolipomas (hamartomas of blood vessels, smooth muscle, and fat).'),
    (v_topic_id, '241. Urothelial (Transitional Cell) Carcinoma is the most common tumor of the urinary tract system (renal pelvis, ureter, bladder). What is the major risk factor?', '["Alcohol", "Cigarette smoking", "High calcium diet", "Recurrent UTIs"]', 1, 'Smoking is the massive #1 risk factor. Others (the P''s): Phenacetin, Pelvic radiation, cyclophosphamide, and occupational exposure to aniline dyes/aromatic amines (Painters/Rubber workers).'),
    (v_topic_id, '242. How does Urothelial Carcinoma classically present?', '["Painful gross hematuria", "Painless gross hematuria", "Microscopic hematuria with casts", "Oliguria"]', 1, 'Painless gross hematuria in an older adult (especially a smoker) is bladder cancer until proven otherwise.'),
    (v_topic_id, '243. Urothelial Carcinoma often has a "field defect". This means?', '["The cancer spreads exclusively via direct extension", "The entire urothelium is exposed to the carcinogen, making multifocal and recurrent tumors very common", "It only affects the left kidney", "It only occurs in the bladder dome"]', 1, 'Because the carcinogens (from smoking/dyes) are bathed over the entire urinary tract, patients frequently develop multiple tumors simultaneously or recurrences over time.'),
    (v_topic_id, '244. Squamous Cell Carcinoma of the bladder is rare in the US but common in the Middle East due to?', '["Smoking", "Schistosoma haematobium infection", "High red meat diet", "Radiation"]', 1, 'Schistosomiasis is a parasitic infection that implants in the bladder wall, causing chronic inflammation and squamous metaplasia, eventually leading to SCC.'),
    (v_topic_id, '245. Adenocarcinoma of the bladder is very rare. It typically arises at the dome of the bladder in association with?', '["A urachal remnant", "Schistosomiasis", "Smoking", "A staghorn calculus"]', 0, 'The urachus connects the fetal bladder to the umbilicus. If it fails to obliterate, the glandular remnant at the bladder dome can undergo malignant transformation to adenocarcinoma.'),

    -- VASCULAR DISORDERS (246-260)
    (v_topic_id, '246. What is the most common cause of Renal Artery Stenosis in an elderly male?', '["Fibromuscular dysplasia", "Atherosclerotic plaque at the origin of the renal artery", "Takayasu arteritis", "Thrombosis"]', 1, 'Atherosclerosis typically affects the proximal third of the renal artery near the aorta in older men with cardiovascular risk factors.'),
    (v_topic_id, '247. What is the most common cause of Renal Artery Stenosis in a young female?', '["Atherosclerosis", "Fibromuscular dysplasia", "Polyarteritis nodosa", "Lupus"]', 1, 'FMD causes a "string of beads" appearance on angiography due to fibromuscular thickening of the vessel wall, typically affecting the mid-to-distal renal artery.'),
    (v_topic_id, '248. In unilateral renal artery stenosis, why does the patient develop severe hypertension?', '["The stenotic kidney secretes massive amounts of renin", "The normal kidney secretes massive amounts of renin", "The adrenal glands hypersecrete aldosterone independently", "The heart increases cardiac output"]', 0, 'The stenotic kidney senses low blood flow (ischemia) and activates the RAAS system, causing systemic vasoconstriction and volume retention.'),
    (v_topic_id, '249. A patient with severe hypertension is started on an ACE inhibitor and their creatinine doubles within days. Diagnosis?', '["Allergic interstitial nephritis", "Bilateral renal artery stenosis", "Renal vein thrombosis", "Aortic dissection"]', 1, 'If both renal arteries are stenotic, the kidneys rely entirely on Angiotensin II to constrict the efferent arteriole to maintain GFR. Blocking AT-II (with an ACEi) causes GFR to plummet.'),
    (v_topic_id, '250. Malignant hypertension is characterized by a rapid, severe rise in BP (>180/120) with end-organ damage. What is the classic renal lesion?', '["Hyaline arteriolosclerosis", "Hyperplastic arteriolosclerosis (onion-skinning) and fibrinoid necrosis", "Crescents", "Wire-loops"]', 1, 'The sudden, extreme pressure causes the smooth muscle cells to rapidly proliferate, creating concentric rings ("onion skin"). High pressure also blows out the vessels, causing fibrinoid necrosis and "flea-bitten" petechial hemorrhages on the kidney surface.'),
    (v_topic_id, '251. Hemolytic Uremic Syndrome (HUS) consists of a triad: Microangiopathic Hemolytic Anemia, Thrombocytopenia, and Acute Renal Failure. What is the classic trigger in children?', '["Streptococcus pneumoniae", "E. coli O157:H7 (Shiga-like toxin)", "Aspirin", "Parvovirus"]', 1, 'Eating undercooked beef infected with E. coli O157:H7 causes bloody diarrhea. The Shiga-like toxin enters the blood, damages endothelial cells, and triggers microthrombi formation.'),
    (v_topic_id, '252. How does the pathogenesis of Thrombotic Thrombocytopenic Purpura (TTP) differ from HUS?', '["TTP involves a defect in ADAMTS13", "TTP is caused by a toxin", "TTP involves massive immune complex deposition", "TTP does not cause thrombocytopenia"]', 0, 'ADAMTS13 normally cleaves large von Willebrand Factor multimers. Without it, massive vWF strings catch platelets, causing systemic microthrombi (prominently affecting the brain and kidneys).'),
    (v_topic_id, '253. A patient undergoes an invasive cardiac catheterization. Days later, they develop acute renal failure, livedo reticularis on the legs, and "blue toes". Diagnosis?', '["Contrast-induced ATN", "Atheroembolic renal disease", "Endocarditis", "Cholesterol granuloma"]', 1, 'The catheter scraped atherosclerotic plaques off the aorta. Cholesterol emboli shower down, lodging in the small renal arteries and peripheral toes. Biopsy shows characteristic needle-shaped cholesterol clefts in the vessels.'),
    (v_topic_id, '254. Sickle cell trait (heterozygotes) usually have normal lifespans. However, the extreme conditions of the renal medulla can trigger sickling, causing?', '["Complete renal failure", "Painless gross hematuria and renal papillary necrosis", "Renal Cell Carcinoma", "Massive proteinuria"]', 1, 'The extreme hypoxia and hyperosmolarity of the renal medulla causes sickling even in heterozygotes, leading to microinfarctions (papillary necrosis) and hematuria. They also lose the ability to concentrate urine (isosthenuria).'),
    (v_topic_id, '255. Renal Vein Thrombosis is most commonly associated with?', '["Minimal Change Disease", "Membranous Nephropathy", "IgA Nephropathy", "Post-streptococcal GN"]', 1, 'The massive loss of Antithrombin III in Nephrotic Syndrome (classically Membranous Nephropathy) leads to a hypercoagulable state.'),

    -- URINARY TRACT INFECTIONS (256-270)
    (v_topic_id, '256. What is the most common organism causing uncomplicated acute cystitis (bladder infection)?', '["Staphylococcus saprophyticus", "Klebsiella pneumoniae", "Escherichia coli", "Proteus mirabilis"]', 2, 'E. coli accounts for >80% of uncomplicated UTIs.'),
    (v_topic_id, '257. A young, sexually active female develops a UTI. E. coli is ruled out. What is the next most likely organism?', '["Staphylococcus saprophyticus", "Pseudomonas aeruginosa", "Enterococcus faecalis", "Serratia marcescens"]', 0, 'S. saprophyticus is a common cause of "honeymoon cystitis".'),
    (v_topic_id, '258. A patient has a UTI with alkaline urine and a large staghorn calculus. Organism?', '["E. coli", "Staphylococcus aureus", "Proteus mirabilis", "Enterococcus"]', 2, 'Proteus (and Klebsiella) produce urease, which splits urea into ammonia, raising the pH and causing struvite precipitation.'),
    (v_topic_id, '259. Sterile pyuria (positive leukocyte esterase/WBCs, but negative standard cultures) strongly suggests?', '["E. coli", "Chlamydia trachomatis or Neisseria gonorrhoeae", "Fungal infection", "Bladder cancer"]', 1, 'Urethritis caused by Chlamydia or Gonorrhea presents with symptoms mimicking cystitis but will not grow on standard urine culture plates.'),
    (v_topic_id, '260. How does Acute Pyelonephritis differ clinically from Acute Cystitis?', '["Pyelonephritis has dysuria, cystitis does not", "Pyelonephritis presents with systemic signs (fever, chills) and flank pain/CVA tenderness", "Pyelonephritis has sterile pyuria", "Cystitis causes renal failure"]', 1, 'Infection ascending to the kidney (pyelonephritis) causes severe systemic inflammation and localized flank pain.'),
    (v_topic_id, '261. What is the pathognomonic urinalysis finding for Acute Pyelonephritis?', '["RBC casts", "Muddy brown casts", "WBC casts", "Hyaline casts"]', 2, 'WBCs aggregate in the infected renal tubules to fight the bacteria, forming casts. Their presence proves the infection is in the kidney, not just the bladder.'),
    (v_topic_id, '262. Chronic Pyelonephritis is most commonly caused by?', '["A single severe infection", "Vesicoureteral reflux (VUR) or chronic obstruction", "Hematogenous seeding", "Autoimmune disease"]', 1, 'Recurrent infections due to abnormal backflow of urine (VUR, common in children) or chronic stones leads to repeated scarring of the kidney.'),
    (v_topic_id, '263. What is the gross morphological hallmark of Chronic Pyelonephritis?', '["Cystic enlargement", "Asymmetric cortical scarring, especially at the upper and lower poles", "Smooth, shrunken kidneys", "Flea-bitten appearance"]', 1, 'The poles are most susceptible to reflux. The scarring is asymmetric, distinguishing it from the symmetric scarring of hypertensive nephrosclerosis.'),
    (v_topic_id, '264. What is the histologic hallmark of Chronic Pyelonephritis?', '["Crescents", "Thyroidization of the kidney", "Kimmelstiel-Wilson nodules", "Granulomas"]', 1, 'Chronic inflammation destroys tubules, and they become dilated and filled with eosinophilic proteinaceous material, making them look exactly like thyroid follicles ("thyroidization").'),
    (v_topic_id, '265. Xanthogranulomatous Pyelonephritis is a rare, severe chronic infection. It is characterized by?', '["Massive numbers of neutrophils", "Granulomatous tissue containing lipid-laden (foamy) macrophages", "Caseating granulomas", "Crescent formation"]', 1, 'Often associated with chronic Proteus infection and staghorn calculi, the kidney is destroyed by yellow, lipid-laden macrophages mimicking a tumor.'),
    (v_topic_id, '266. A diabetic patient presents with severe flank pain, fever, and gas in the renal parenchyma on CT scan. Diagnosis?', '["Emphysematous Pyelonephritis", "Xanthogranulomatous Pyelonephritis", "Renal Papillary Necrosis", "Abscess"]', 0, 'A life-threatening necrotizing infection caused by gas-producing bacteria (like E. coli) occurring almost exclusively in diabetics.'),
    (v_topic_id, '267. What is the most common route of infection for pyelonephritis?', '["Ascending from the bladder", "Hematogenous (from the blood)", "Lymphatic spread", "Direct trauma"]', 0, 'Bacteria climb from the urethra -> bladder -> ureters -> kidney.'),
    (v_topic_id, '268. Which organism typically causes pyelonephritis via HEMATOGENOUS seeding (e.g., from endocarditis)?', '["E. coli", "Proteus", "Staphylococcus aureus", "Klebsiella"]', 2, 'S. aureus in the blood can seed the kidneys, causing multiple small cortical abscesses rather than ascending tubule infection.'),
    (v_topic_id, '269. The presence of nitrites on a urine dipstick indicates the presence of?', '["Any bacteria", "Gram-negative bacteria (like E. coli)", "Gram-positive bacteria (like Enterococcus)", "Fungi"]', 1, 'Enterobacteriaceae (Gram-negatives) reduce dietary nitrates to nitrites.'),
    (v_topic_id, '270. Acute Pyelonephritis typically involves which parts of the kidney?', '["Glomeruli only", "Tubules and interstitium, sparing the glomeruli", "Blood vessels only", "The renal capsule only"]', 1, 'The infection tracks up the tubules. The glomeruli are remarkably resistant to infection and are typically spared.'),

    -- ACID-BASE, ELECTROLYTES & RTA (271-285)
    (v_topic_id, '271. Type 1 (Distal) Renal Tubular Acidosis is caused by?', '["Failure of the PCT to reabsorb Bicarbonate", "Failure of the alpha-intercalated cells in the collecting duct to secrete H+", "Hypoaldosteronism", "Failure of ADH"]', 1, 'The distal tubule cannot secrete acid. Therefore, urine pH remains > 5.5 despite severe systemic metabolic acidosis.'),
    (v_topic_id, '272. What is a classic complication of Type 1 RTA?', '["Calcium Phosphate kidney stones", "Uric acid stones", "Renal Cell Carcinoma", "Massive proteinuria"]', 0, 'The inability to acidify urine means the urine is constantly alkaline. This, combined with bone buffering (releasing calcium), perfectly sets up Calcium Phosphate stone formation.'),
    (v_topic_id, '273. Type 2 (Proximal) Renal Tubular Acidosis is caused by?', '["Failure of the alpha-intercalated cells to secrete H+", "Hypoaldosteronism", "Failure of the Proximal Convoluted Tubule to reabsorb filtered Bicarbonate", "Carbonic anhydrase overactivity"]', 2, 'The PCT dumps bicarbonate into the urine. However, the distal tubule is intact and eventually reabsorbs the distal load, so the urine CAN be acidified (pH < 5.5) once the systemic bicarbonate drops low enough.'),
    (v_topic_id, '274. Fanconi Syndrome involves a generalized defect in the PCT. This causes Type 2 RTA and the loss of which other substances?', '["Glucose, Amino acids, Uric acid, and Phosphate", "Sodium and Potassium only", "Red blood cells and protein", "Water only"]', 0, 'The PCT fails completely, spilling glucose (with normal blood sugar), amino acids, phosphate, and bicarbonate.'),
    (v_topic_id, '275. Type 4 Renal Tubular Acidosis is caused by?', '["Hypoaldosteronism or aldosterone resistance", "Carbonic anhydrase deficiency", "PCT failure", "Distal H+ pump failure"]', 0, 'Lack of aldosterone action means Na+ is not reabsorbed, and K+ and H+ are not secreted. This causes Hyperkalemia and metabolic acidosis.'),
    (v_topic_id, '276. Which RTA is the ONLY one associated with Hyperkalemia?', '["Type 1", "Type 2", "Type 4", "None"]', 2, 'Types 1 and 2 cause Hypokalemia. Type 4 (due to lack of aldosterone) causes Hyperkalemia.'),
    (v_topic_id, '277. Diabetic Nephropathy frequently damages the JGA, leading to low Renin and low Aldosterone. Which RTA do they develop?', '["Type 1", "Type 2", "Type 4", "Type 3"]', 2, 'Hyporeninemic hypoaldosteronism causes Type 4 RTA.'),
    (v_topic_id, '278. Bartter Syndrome is a genetic defect in which transporter?', '["Na-K-2Cl in the thick ascending limb", "Na-Cl in the distal convoluted tubule", "ENaC in the collecting duct", "Carbonic anhydrase in the PCT"]', 0, 'Bartter syndrome acts exactly like a chronic Loop Diuretic (Furosemide). It causes severe hypokalemia, metabolic alkalosis, and hypercalciuria.'),
    (v_topic_id, '279. Gitelman Syndrome is a genetic defect in which transporter?', '["Na-K-2Cl in the thick ascending limb", "Na-Cl cotransporter in the distal convoluted tubule", "ENaC in the collecting duct", "Aquaporin 2"]', 1, 'Gitelman syndrome acts exactly like a chronic Thiazide diuretic. It causes hypokalemia, metabolic alkalosis, but HYPOcalciuria (unlike Bartter).'),
    (v_topic_id, '280. Liddle Syndrome is a gain-of-function mutation in?', '["Na-K-2Cl", "ENaC (Epithelial Sodium Channel)", "Na-Cl cotransporter", "Aldosterone receptor"]', 1, 'The ENaC channel is stuck "open," reabsorbing massive sodium and dumping potassium/H+. It perfectly mimics hyperaldosteronism, but aldosterone levels are nearly zero.'),
    (v_topic_id, '281. Syndrome of Inappropriate ADH (SIADH) causes which electrolyte abnormality?', '["Hypernatremia", "Hypokalemia", "Euvolemic Hyponatremia", "Hypervolemic Hypernatremia"]', 2, 'Excess ADH causes pure water reabsorption. This dilutes the serum sodium (hyponatremia). The body responds by dumping sodium in the urine to try and shed volume, maintaining euvolemia.'),
    (v_topic_id, '282. Central Diabetes Insipidus is caused by a lack of ADH. The urine is?', '["Highly concentrated", "Dilute (low specific gravity and low osmolality)", "Full of glucose", "Bloody"]', 1, 'Without ADH, the collecting ducts are impermeable to water. Massive amounts of pure, dilute water are lost, causing hypernatremia in the blood.'),
    (v_topic_id, '283. Lithium famously causes which renal side effect?', '["Central Diabetes Insipidus", "Nephrogenic Diabetes Insipidus", "SIADH", "Fanconi Syndrome"]', 1, 'Lithium enters the collecting duct cells and interferes with the insertion of Aquaporin-2 channels, rendering the kidney deaf to ADH.'),
    (v_topic_id, '284. How does the kidney compensate for chronic respiratory acidosis (e.g., COPD)?', '["Secreting bicarbonate", "Retaining/reabsorbing bicarbonate and excreting H+ (as NH4+)", "Hyperventilating", "Retaining chloride"]', 1, 'The kidney ramps up bicarbonate reabsorption and production over 3-5 days to buffer the high CO2.'),
    (v_topic_id, '285. In a patient with severe vomiting, what is the primary cause of the maintenance of metabolic alkalosis?', '["Loss of H+ in the vomit", "Volume depletion triggers Aldosterone, which forces the kidney to dump H+ and K+ to save Sodium", "Loss of chloride", "Hyperventilation"]', 1, 'While losing H+ initiates the alkalosis, the volume depletion (contraction) forces the kidney to retain Na+ at all costs via Aldosterone. Aldosterone trades Na+ for H+ and K+, preventing the kidney from excreting the excess bicarbonate (contraction alkalosis).'),

    -- FINAL COMPREHENSIVE REVIEW (286-300)
    (v_topic_id, '286. Which drug class dilates the afferent arteriole, maintaining GFR?', '["ACE inhibitors", "Prostaglandins", "NSAIDs", "Norepinephrine"]', 1, 'Prostaglandins dilate the Afferent arteriole (PDA). NSAIDs block them, causing constriction and dropping GFR.'),
    (v_topic_id, '287. Which hormone constricts the efferent arteriole, maintaining GFR in low-flow states?', '["Prostaglandins", "Angiotensin II", "Aldosterone", "ADH"]', 1, 'Angiotensin II constricts the Efferent arteriole (ACE). ACE inhibitors block this, dilating the efferent and dropping GFR.'),
    (v_topic_id, '288. Where is the majority of water, sodium, glucose, and amino acids reabsorbed?', '["Proximal Convoluted Tubule (PCT)", "Thick Ascending Limb", "Distal Convoluted Tubule", "Collecting Duct"]', 0, 'The PCT does the heavy lifting, reabsorbing ~67% of water and Na+, and 100% of glucose and amino acids.'),
    (v_topic_id, '289. The Macula Densa senses?', '["Sodium chloride delivery to the distal tubule", "Blood pressure in the afferent arteriole", "Oxygen tension", "Glucose levels"]', 0, 'Located in the distal tubule, the macula densa senses NaCl. If NaCl is low (due to low GFR), it signals the juxtaglomerular cells to release Renin.'),
    (v_topic_id, '290. Renin is secreted by which cells?', '["Macula Densa", "Juxtaglomerular (JG) cells in the afferent arteriole", "Mesangial cells", "Podocytes"]', 1, 'JG cells are modified smooth muscle cells in the afferent arteriole that act as baroreceptors and secrete Renin when pressure falls.'),
    (v_topic_id, '291. Erythropoietin (EPO) is produced by?', '["JG cells", "Macula Densa", "Interstitial fibroblasts in the peritubular capillary bed", "Glomerular endothelial cells"]', 2, 'These fibroblasts sense hypoxia and release EPO to stimulate red blood cell production in the bone marrow.'),
    (v_topic_id, '292. Vitamin D is converted to its active form (1,25-OH) by which enzyme in the kidney?', '["25-hydroxylase", "1-alpha-hydroxylase", "Aldosterone synthase", "Renin"]', 1, '1-alpha-hydroxylase in the PCT (stimulated by PTH) performs the final activation of Vitamin D.'),
    (v_topic_id, '293. Dopamine, secreted by the proximal tubule, has what effect at low doses?', '["Constricts both arterioles", "Dilates interlobular arteries, afferent arterioles, and efferent arterioles, increasing Renal Blood Flow", "Stops urine production", "Triggers renin release"]', 1, 'Low-dose dopamine improves renal perfusion. High doses (acting on alpha receptors) cause vasoconstriction.'),
    (v_topic_id, '294. Atrial Natriuretic Peptide (ANP) dilates the afferent arteriole and constricts the efferent arteriole. What is the net effect on GFR?', '["Decreases GFR", "Increases GFR", "No change", "Stops filtration completely"]', 1, 'Opening the entrance (afferent) and closing the exit (efferent) maximizes the pressure in the glomerulus, greatly increasing GFR to shed volume (natriuresis).'),
    (v_topic_id, '295. Which section of the loop of Henle is impermeable to water?', '["Thin descending limb", "Thick ascending limb", "Proximal tubule", "Collecting duct in presence of ADH"]', 1, 'The thick ascending limb actively pumps out salts (Na-K-2Cl) but lets no water follow. This dilutes the urine and makes the medullary interstitium salty.'),
    (v_topic_id, '296. Acetazolamide works by inhibiting Carbonic Anhydrase. What is the clinical result?', '["Metabolic alkalosis", "Massive diuresis", "Bicarbonate dumping in the urine, causing mild metabolic acidosis", "Hypernatremia"]', 2, 'By blocking bicarb reabsorption in the PCT, it alkalinizes the urine and acidifies the blood (useful for altitude sickness and glaucoma).'),
    (v_topic_id, '297. Loop diuretics (Furosemide) cause hypocalcemia. Thiazides cause?', '["Hypocalcemia", "Hypercalcemia (Hypercalciuria)", "Hypercalcemia (Hypocalciuria)", "No effect on calcium"]', 2, 'Thiazides increase calcium reabsorption in the DCT, leading to low urine calcium (hypocalciuria) and slightly high blood calcium. They are used to PREVENT calcium kidney stones.'),
    (v_topic_id, '298. Spironolactone and Eplerenone are Potassium-Sparing diuretics. They act on which segment?', '["PCT", "Loop of Henle", "DCT", "Cortical Collecting Duct"]', 3, 'They block the Aldosterone receptor in the principal cells, preventing Na+ reabsorption and preventing K+/H+ loss.'),
    (v_topic_id, '299. Mannitol is an osmotic diuretic used primarily to treat?', '["Heart failure", "Hypertension", "Cerebral edema and increased intraocular pressure", "Hyperkalemia"]', 2, 'Mannitol stays in the blood and tubules, pulling water out of the brain (reducing intracranial pressure). It is contraindicated in heart failure as it initially expands intravascular volume.'),
    (v_topic_id, '300. A patient on an ACE inhibitor develops a dry, hacking cough. What is the mechanism?', '["Pulmonary edema", "Accumulation of Bradykinin", "Allergic reaction", "Bronchospasm from beta block"]', 1, 'ACE normally degrades Bradykinin. Blocking ACE leads to high bradykinin, which irritates the lungs (cough) and can cause dangerous angioedema. Switching to an ARB (Losartan) fixes this.');

    RAISE NOTICE 'SUCCESS: Renal Pathology MCQs Part 4 (226-300) registered.';
END $$;

COMMIT;
